-- Task 9.4 (invites and users). Generated by drizzle-kit, then edited by hand:
-- the AUTOINCREMENT counter of `api_keys` is kept across the rebuild, so a key
-- ID is never handed out twice. `api_keys` is rebuilt so the creator and the
-- revoker become `ON DELETE SET NULL` (a user can now be deleted). The PRAGMA
-- lines are no-ops: `migrate()` (db/index.ts) runs with foreign keys off and
-- runs `foreign_key_check` before commit.
CREATE TABLE `invites` (
	`id` text PRIMARY KEY NOT NULL,
	`type` text NOT NULL,
	`token_hash` text NOT NULL,
	`label` text,
	`created_by` integer,
	`created_at` text NOT NULL,
	`expires_at` text NOT NULL,
	`role` text,
	`can_create_api_keys` integer,
	`target_user_id` integer,
	`used_at` text,
	`used_by` integer,
	`revoked_at` text,
	`revoked_by` integer,
	FOREIGN KEY (`created_by`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE set null,
	FOREIGN KEY (`target_user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`used_by`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE set null,
	FOREIGN KEY (`revoked_by`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE set null
);
--> statement-breakpoint
CREATE UNIQUE INDEX `invites_token_hash_unique` ON `invites` (`token_hash`);--> statement-breakpoint
CREATE INDEX `invites_type_target_idx` ON `invites` (`type`,`target_user_id`);--> statement-breakpoint
CREATE INDEX `invites_created_at_idx` ON `invites` (`created_at`);--> statement-breakpoint
PRAGMA foreign_keys=OFF;--> statement-breakpoint
CREATE TABLE `__new_api_keys` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`user_id` integer NOT NULL,
	`created_by_user_id` integer,
	`revoked_by_user_id` integer,
	`name` text NOT NULL,
	`key_hash` text NOT NULL,
	`prefix` text NOT NULL,
	`created_at` text NOT NULL,
	`last_used_at` text,
	`revoked_at` text,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`created_by_user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE set null,
	FOREIGN KEY (`revoked_by_user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE set null
);
--> statement-breakpoint
INSERT INTO `__new_api_keys`("id", "user_id", "created_by_user_id", "revoked_by_user_id", "name", "key_hash", "prefix", "created_at", "last_used_at", "revoked_at") SELECT "id", "user_id", "created_by_user_id", "revoked_by_user_id", "name", "key_hash", "prefix", "created_at", "last_used_at", "revoked_at" FROM `api_keys`;--> statement-breakpoint
UPDATE `sqlite_sequence` SET `seq` = (SELECT `seq` FROM `sqlite_sequence` WHERE `name` = 'api_keys')
	WHERE `name` = '__new_api_keys' AND EXISTS (SELECT 1 FROM `sqlite_sequence` WHERE `name` = 'api_keys');--> statement-breakpoint
